import sys
import json

# Step kinds
GET = 0
SET = 1   # put/del -> unconditional write (value or None)
CAS = 2
SCAN = 3
FAIL = 4  # can never match


def run_tx(steps, st):
    st = list(st)
    for step in steps:
        k = step[0]
        if k == GET:
            if st[step[1]] != step[2]:
                return None
        elif k == SET:
            st[step[1]] = step[2]
        elif k == CAS:
            ok = st[step[1]] == step[2]
            if ok != step[4]:
                return None
            if ok:
                st[step[1]] = step[3]
        elif k == SCAN:
            idxs = step[1]
            exp = step[2]
            for j in range(len(idxs)):
                if st[idxs[j]] != exp[j]:
                    return None
        else:
            return None
    return tuple(st)


def compile_tx(ops, kidx):
    steps = []
    for op in ops:
        kind = op[0]
        if kind == 'get':
            steps.append((GET, kidx[op[1]], op[2]))
        elif kind == 'put':
            steps.append((SET, kidx[op[1]], op[2]))
        elif kind == 'del':
            steps.append((SET, kidx[op[1]], None))
        elif kind == 'cas':
            steps.append((CAS, kidx[op[1]], op[2], op[3], op[4]))
        elif kind == 'scan':
            low, high, pairs = op[1], op[2], op[3]
            expmap = {}
            fail = False
            if pairs != sorted(pairs):
                fail = True
            else:
                for key, val in pairs:
                    if not (low <= key < high) or key not in kidx or key in expmap:
                        fail = True
                        break
                    expmap[kidx[key]] = val
            if fail:
                steps.append((FAIL,))
            else:
                idxs = tuple(i for key, i in kidx.items() if low <= key < high)
                exp = tuple(expmap.get(i) for i in idxs)
                steps.append((SCAN, idxs, exp))
        else:
            steps.append((FAIL,))
    return steps


def solve(req):
    txs = req['transactions']
    n = len(txs)
    initial = req['initial']
    final = req['final']

    # key universe: anything that can ever be present
    keys = set(initial) | set(final)
    for t in txs:
        for op in t['ops']:
            if op[0] != 'scan':
                keys.add(op[1])
    keys = sorted(keys)
    kidx = {k: i for i, k in enumerate(keys)}
    U = len(keys)

    init_t = tuple(initial.get(k) for k in keys)
    final_t = tuple(final.get(k) for k in keys)

    comps = [compile_tx(t['ops'], kidx) for t in txs]

    # may-write analysis: tx -> dict idx -> frozenset of values it may leave
    mw = []
    for steps in comps:
        d = {}
        for step in steps:
            if step[0] == SET:
                d[step[1]] = frozenset((step[2],))
            elif step[0] == CAS:
                i = step[1]
                d[i] = d.get(i, frozenset()) | frozenset((step[3],))
        mw.append(d)

    # real-time precedence: a before b iff a.end <= b.start
    pred = [0] * n
    for i in range(n):
        ei = txs[i]['end']
        for j in range(n):
            if i != j and ei <= txs[j]['start']:
                pred[j] |= 1 << i

    full = (1 << n) - 1
    ids = [t['id'] for t in txs]
    order = []
    memo = set()

    def bt(mask, st):
        if mask == full:
            return st == final_t
        mkey = (mask, st)
        if mkey in memo:
            return False
        rem = full ^ mask
        # necessary-condition prune: each key's final value must be
        # achievable as current value or via some remaining tx's writes
        for i in range(U):
            want = final_t[i]
            if want == st[i]:
                continue
            ok = False
            m = rem
            while m:
                b = m & (-m)
                t = b.bit_length() - 1
                vs = mw[t].get(i)
                if vs is not None and want in vs:
                    ok = True
                    break
                m ^= b
            if not ok:
                memo.add(mkey)
                return False
        for t in range(n):
            if (mask >> t) & 1 or pred[t] & ~mask:
                continue
            ns = run_tx(comps[t], st)
            if ns is not None:
                order.append(t)
                if bt(mask | (1 << t), ns):
                    return True
                order.pop()
        memo.add(mkey)
        return False

    if bt(0, init_t):
        return {'order': [ids[t] for t in order]}
    return {'order': None}


if __name__ == '__main__':
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.write(json.dumps(solve(json.loads(line))) + '\n')
    out.flush()
