            if r<0.25: ops.append(["get",k,val()])
            elif r<0.45: ops.append(["put",k,pval()])
            elif r<0.55: ops.append(["del",k])
            elif r<0.75: ops.append(["cas",k,val(),rng.choice([None,pval()]),rng.choice([True,False])])
